cloze=[
{"title":"大正政変と第一次世界大戦","text":"陸軍の[[2個師団の増設]]要求をことわった第2次西園寺内閣が倒れ、第3次桂内閣ができると、尾崎行雄・犬養毅らは「閥族打破・憲政擁護」をかかげて[[第1次護憲運動]]をおこし、内閣を退陣させた。これを[[大正政変]]という。つづく山本権兵衛内閣は、海軍の汚職事件である[[シーメンス事件]]で退陣した。第2次大隈内閣は、外相[[加藤高明]]の主導で[[日英同盟]]を理由に第一次世界大戦に参戦し、1915年には袁世凱政府に[[二十一カ条の要求]]をつきつけた。寺内内閣は段祺瑞政権に[[西原借款]]を与え、1917年には[[石井・ランシング協定]]を結んだ。ロシア革命がおこると、1918年に[[シベリア出兵]]をおこなった。"},
{"title":"政党政治と社会運動","text":"[[吉野作造]]は、天皇主権の憲法の枠内で民衆の幸福を政治の目的とする[[民本主義]]をとなえた。1918年、富山県から全国に広がった[[米騒動]]で寺内内閣が倒れると、立憲政友会の[[原敬]]が初の本格的政党内閣をつくった。社会運動もさかんになり、鈴木文治の[[友愛会]]はのちに日本労働総同盟となった。平塚らいてう・市川房枝らは[[新婦人協会]]をつくり、1922年には部落差別の解消をめざす[[全国水平社]]がつくられた。1924年、清浦内閣に反対する[[第2次護憲運動]]がおこり、護憲三派の連立内閣は1925年に[[普通選挙法]]と[[治安維持法]]を成立させた。"},
{"title":"国際協調と大正の経済・文化","text":"1919年の[[ヴェルサイユ条約]]で、日本は南洋諸島の[[委任統治]]を認められたが、中国では[[五・四運動]]、朝鮮では[[三・一独立運動]]がおこった。ワシントン会議では、[[四カ国条約]]で太平洋の現状維持が決まり、[[九カ国条約]]で中国の主権尊重が約束された。大戦中は[[大戦景気]]で輸出が増え、海運業では[[船成金]]が生まれ、日本は債務国から[[債権国]]になった。都市には[[俸給生活者]]が増え、1918年の[[大学令]]で大学も増えた。文学では有島武郎・志賀直哉らの[[白樺派]]が活躍し、1925年には[[ラジオ放送]]が始まった。"}]
ans=[]
for c in cloze: ans+=re.findall(r'\[\[([^\]]+)\]\]',c['text'])
pl=''.join(re.sub(r'\[\[[^\]]+\]\]','□',c['text']) for c in cloze)
print('cloze',len(ans),'dup',[a for a in set(ans) if ans.count(a)>1],'leak',[a for a in set(ans) if a in pl],'overlap',[(a,b) for a in set(ans) for b in set(ans) if a!=b and a in b])
notin=[a for a in ans if not any(a in t for t in txt.values())]; print('cloze-not-in-lessons',notin)

